@'
import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
const installed=path.join(process.env.APPDATA,'npm/node_modules/@vxu-labs/dip');
for(const folder of ['src','bin','public','skills/dip']) for(const name of fs.readdirSync(folder)) {
 const local=path.join(folder,name), remote=path.join(installed,folder,name);
 if(!fs.statSync(local).isFile()) continue;
 if(createHash('sha256').update(fs.readFileSync(local)).digest('hex')!==createHash('sha256').update(fs.readFileSync(remote)).digest('hex')) throw Error('Installed source differs: '+local);
}
console.log('Installed runtime, dashboard and skill match the published source.');
'@ | node --input-type=module
